DO $$ BEGIN
IF (SELECT count(*) FROM desired_teen_exercises) <> 90 THEN RAISE EXCEPTION 'Expected 90 exercises'; END IF;
IF EXISTS (SELECT level FROM desired_teen_exercises GROUP BY level HAVING count(*)<>CASE level WHEN 1 THEN 16 WHEN 2 THEN 16 WHEN 3 THEN 18 ELSE 20 END) OR (SELECT count(DISTINCT level) FROM desired_teen_exercises)<>5 THEN RAISE EXCEPTION 'Unexpected level distribution'; END IF;
IF EXISTS (SELECT 1 FROM desired_teen_exercises d LEFT JOIN speed_reading.exercise_types t ON t.name=d.type AND NOT t.is_deleted AND t.is_active WHERE t.id IS NULL OR t.engine_type<>d.config->>'engineType') THEN RAISE EXCEPTION 'Exercise type mismatch'; END IF;
IF EXISTS (SELECT 1 FROM desired_teen_exercises d WHERE NOT EXISTS (SELECT 1 FROM speed_reading.reading_texts r WHERE r.target_age_group_id=d.age AND r.difficulty_level=d.level AND r.is_active AND NOT r.is_deleted)) THEN RAISE EXCEPTION 'Missing reading text pool'; END IF;
END $$;
INSERT INTO speed_reading.exercises(id,exercise_type_id,title,description,type_code,difficulty_level,configuration_json,target_age_group_id,creator_id,is_active,created_at,created_by,version,is_deleted)
SELECT d.id,t.id,d.title,d.description,d.type,d.level,d.config,d.age,'b993e2f8-3948-49bd-9cbd-463e8771c20d'::uuid,true,now(),'system:teen-exercises-v1',1,false
FROM desired_teen_exercises d JOIN speed_reading.exercise_types t ON t.name=d.type AND NOT t.is_deleted AND t.is_active
ON CONFLICT(id) DO NOTHING;
DO $$ BEGIN
IF EXISTS (SELECT 1 FROM desired_teen_exercises d LEFT JOIN speed_reading.exercises e ON e.id=d.id WHERE e.id IS NULL OR e.configuration_json<>d.config OR e.difficulty_level<>d.level OR e.target_age_group_id<>d.age OR NOT e.is_active OR e.is_deleted) THEN RAISE EXCEPTION 'Catalog verification failed'; END IF;
END $$;
