INSERT INTO speed_reading.visualization_scenes(id,exercise_id,description,duration,display_order,difficulty_level,target_age_group_id,mode,is_deleted,created_at,created_by,version)
SELECT (item->>'id')::uuid,(item->>'exerciseId')::uuid,item->>'description',(item->>'duration')::int,(item->>'displayOrder')::int,(item->>'difficultyLevel')::int,(item->>'targetAgeGroupId')::uuid,item->>'mode',false,now(),'system:teen-exercises-v1',1 FROM desired_scenes ON CONFLICT(id) DO NOTHING;
INSERT INTO speed_reading.visualization_questions(id,scene_id,question_text,options_json,correct_answer,question_type,display_order,is_deleted,created_at,created_by,version)
SELECT (q->>'id')::uuid,(item->>'id')::uuid,q->>'questionText',q->'options',q->>'correctAnswer',q->>'questionType',(q->>'displayOrder')::int,false,now(),'system:teen-exercises-v1',1 FROM desired_scenes CROSS JOIN LATERAL jsonb_array_elements(item->'questions') q ON CONFLICT(id) DO NOTHING;
DO $$ BEGIN
IF (SELECT count(*) FROM speed_reading.visualization_scenes WHERE id IN (SELECT (item->>'id')::uuid FROM desired_scenes) AND NOT is_deleted)<>15 THEN RAISE EXCEPTION 'Expected 15 scenes'; END IF;
IF (SELECT count(*) FROM speed_reading.visualization_questions WHERE scene_id IN (SELECT (item->>'id')::uuid FROM desired_scenes) AND NOT is_deleted)<>45 THEN RAISE EXCEPTION 'Expected 45 scene questions'; END IF;
END $$;
SELECT difficulty_level,count(*) FROM speed_reading.exercises WHERE id IN (SELECT id FROM desired_teen_exercises) GROUP BY difficulty_level ORDER BY difficulty_level;
COMMIT;
